(function() {
    'use strict';

    class DesignThinkAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'DesignThink: Human-Centered Innovation';
            this.version = '1.1.1';

            // Minimum cost/hours of the cheapest legal play in each FUTURE round.
            // Validation reserves these so random events can never soft-lock a team (EQIL B1).
            this.BUDGET_RESERVE = { 1: 14000, 2: 9000, 3: 4000, 4: 0 };
            this.HOURS_RESERVE  = { 1: 20,    2: 15,   3: 5,    4: 0 };

            // Briefings and stage names live in getTranslations() and render via
            // _t() — never via manual language branching. See
            // Lessons_Learned_USF_i18n_and_Modals.md: the framework's canonical
            // language property is window.mySimulation.language; adapters that
            // branch on .currentLanguage render English inside a Spanish UI.
            this.ROUNDS = [
                { icon: '👁', stageKey: 'stage_empathize', briefKey: 'brief_r1' },
                { icon: '🎯', stageKey: 'stage_define',    briefKey: 'brief_r2' },
                { icon: '💡', stageKey: 'stage_ideate',    briefKey: 'brief_r3' },
                { icon: '🧪', stageKey: 'stage_test',      briefKey: 'brief_r4' }
            ];

            this.HMW_OPTIONS = [
                { id: 1, insightMatch: 0.2 },
                { id: 2, insightMatch: 1.0 },
                { id: 3, insightMatch: 0.3 },
                { id: 4, insightMatch: 0.85 }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 240000,
                    teamHours: 120,
                    insightScore: 0,
                    problemClarity: 0,
                    prototypeFit: 0,
                    stakeholderAlignment: 50,
                    processDiscipline: 0,
                    innovationScore: 0,
                    learningYield: 0,
                    empathyComplete: false,
                    defineComplete: false,
                    prototypeBuilt: false,
                    hmwChoice: 0,
                    prototypeTypeChosen: 0,
                    penalties: [],
                    activeEvent: null,
                    events: {},        // persisted random rolls (EQIL M1): rolled once, undo-safe
                    checkpoints: {},   // pre-round snapshots for idempotent recompute (EQIL M1)
                    scoreHistory: [],
                    budgetHistory: [],
                    insightHistory: [],
                    alignmentHistory: []
                };
            }
            var ds = state.domainState;
            if (!ds.events) ds.events = {};
            if (!ds.checkpoints) ds.checkpoints = {};
            if (ds.learningYield === undefined) ds.learningYield = 0;
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    interviewHours: 15,
                    observationHours: 10,
                    deskReviewHours: 5,
                    segmentFocus: 1,
                    hmwChoice: 4,
                    convergenceHours: 12,
                    stakeholderUpdate: 1,
                    ideationApproach: 1,
                    prototypeType: 1,
                    prototypeBudget: 10000,
                    stakeholderExpectation: 1,
                    authorityResponse: 1,
                    testMethod: 1,
                    testParticipants: 15,
                    finalDecision: 1
                };
            }
            this._updateBriefing(state);
        }

        // ---------- helpers ----------

        // Clamped integer read (EQIL M2): typed negatives / out-of-range / NaN can
        // neither refund budget nor bypass limits.
        _readInt(id, min, max, fallback) {
            var el = document.getElementById(id);
            if (!el) return fallback;
            var v = parseInt(el.value, 10);
            if (isNaN(v)) return fallback;
            return Math.max(min, Math.min(max, v));
        }

        // Persist a random roll so results are reproducible and undo-safe (EQIL M1).
        _roll(ds, tag, prob) {
            if (!ds.events) ds.events = {};
            if (ds.events[tag] === undefined) ds.events[tag] = (Math.random() < prob);
            return ds.events[tag];
        }

        // Robust language detection (Lessons_Learned_USF_i18n_and_Modals.md):
        // .language is canonical; .currentLanguage and <html lang> are fallbacks.
        _lang() {
            var sim = window.mySimulation;
            if (sim && sim.language) return sim.language;
            if (sim && sim.currentLanguage) return sim.currentLanguage;
            try {
                var dl = document.documentElement.getAttribute('lang');
                if (dl) return dl.split('-')[0];
            } catch (e) {}
            return 'en';
        }

        // Translation helper usable outside the framework's data-i18n pass.
        _t(key) {
            try {
                if (window.mySimulation && window.mySimulation.t) {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            var lang = this._lang();
            var cat = this.getTranslations();
            return (cat[lang] && cat[lang][key]) || cat.en[key] || key;
        }

        _snapshot(ds) {
            return {
                budget: ds.budget, teamHours: ds.teamHours,
                insightScore: ds.insightScore, problemClarity: ds.problemClarity,
                prototypeFit: ds.prototypeFit, stakeholderAlignment: ds.stakeholderAlignment,
                processDiscipline: ds.processDiscipline, innovationScore: ds.innovationScore,
                learningYield: ds.learningYield,
                empathyComplete: ds.empathyComplete, defineComplete: ds.defineComplete,
                prototypeBuilt: ds.prototypeBuilt, hmwChoice: ds.hmwChoice,
                prototypeTypeChosen: ds.prototypeTypeChosen,
                penalties: ds.penalties.slice(), activeEvent: ds.activeEvent
            };
        }

        _restore(ds, snap, round) {
            ds.budget = snap.budget; ds.teamHours = snap.teamHours;
            ds.insightScore = snap.insightScore; ds.problemClarity = snap.problemClarity;
            ds.prototypeFit = snap.prototypeFit; ds.stakeholderAlignment = snap.stakeholderAlignment;
            ds.processDiscipline = snap.processDiscipline; ds.innovationScore = snap.innovationScore;
            ds.learningYield = snap.learningYield;
            ds.empathyComplete = snap.empathyComplete; ds.defineComplete = snap.defineComplete;
            ds.prototypeBuilt = snap.prototypeBuilt; ds.hmwChoice = snap.hmwChoice;
            ds.prototypeTypeChosen = snap.prototypeTypeChosen;
            ds.penalties = snap.penalties.slice(); ds.activeEvent = snap.activeEvent;
            ds.scoreHistory.length = round - 1;
            ds.budgetHistory.length = round - 1;
            ds.insightHistory.length = round - 1;
            ds.alignmentHistory.length = round - 1;
        }

        _pushHistory(ds, round, score) {
            ds.scoreHistory[round - 1] = score;
            ds.budgetHistory[round - 1] = ds.budget;
            ds.insightHistory[round - 1] = ds.insightScore;
            ds.alignmentHistory[round - 1] = ds.stakeholderAlignment;
        }

        _r3ExpectationCost(v) { return v === 1 ? 3000 : v === 2 ? 500 : 0; }
        _r3ResponseCost(v)    { return v === 1 ? 8000 : v === 2 ? 4000 : 0; }

        // ---------- validation ----------

        validateDecisions(decisions) {
            var currentState = window.mySimulation.state;
            var ds = currentState.domainState;
            var round = currentState.currentPeriod;
            this._updateBriefing(currentState);
            var warn = function(key) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t(key), 'warning');
                return false;
            };

            if (round === 1) {
                decisions.interviewHours   = this._readInt('interviewHoursInput', 0, 50, 15);
                decisions.observationHours = this._readInt('observationHoursInput', 0, 40, 10);
                decisions.deskReviewHours  = this._readInt('deskReviewHoursInput', 0, 20, 5);
                decisions.segmentFocus     = this._readInt('segmentFocusSelect', 1, 3, 1);

                var totalHours = decisions.interviewHours + decisions.observationHours + decisions.deskReviewHours;
                if (totalHours < 5) return warn('min_hours_warning');
                // +5 = allowance for the contradictory-finding event (EQIL B1)
                if (totalHours + 5 > ds.teamHours - this.HOURS_RESERVE[1]) return warn('hours_reserve_warning');
                var totalCost = (decisions.interviewHours * 2000) + (decisions.observationHours * 1500) + (decisions.deskReviewHours * 800);
                if (totalCost > ds.budget - this.BUDGET_RESERVE[1]) return warn('budget_reserve_warning');

            } else if (round === 2) {
                decisions.hmwChoice         = this._readInt('hmwSelect', 1, 4, 4);
                decisions.convergenceHours  = this._readInt('convergenceHoursInput', 5, 30, 12);
                decisions.stakeholderUpdate = this._readInt('stakeholderUpdateSelect', 1, 3, 1);

                if (decisions.convergenceHours > ds.teamHours - this.HOURS_RESERVE[2]) return warn('hours_reserve_warning');
                var stakeCost = decisions.stakeholderUpdate === 1 ? 5000 : decisions.stakeholderUpdate === 2 ? 1000 : 0;
                if ((decisions.convergenceHours * 1000) + stakeCost > ds.budget - this.BUDGET_RESERVE[2]) return warn('budget_reserve_warning');

            } else if (round === 3) {
                decisions.ideationApproach       = this._readInt('ideationSelect', 1, 3, 1);
                decisions.prototypeType          = this._readInt('prototypeSelect', 1, 4, 1);
                decisions.prototypeBudget        = this._readInt('prototypeBudgetInput', 0, 80000, 0);
                decisions.stakeholderExpectation = this._readInt('stakeholderExpSelect', 1, 3, 1);
                decisions.authorityResponse      = this._readInt('authorityResponseSelect', 1, 3, 1);

                var ideaHours = decisions.ideationApproach === 1 ? 20 : decisions.ideationApproach === 2 ? 10 : 15;
                if (ideaHours > ds.teamHours - this.HOURS_RESERVE[3]) return warn('hours_reserve_warning');
                var ideaCost = decisions.ideationApproach === 3 ? 15000 : 0;
                var protoCosts = [5000, 8000, 25000, 35000];
                var protoBase = protoCosts[decisions.prototypeType - 1] || 5000;
                var expCost = this._r3ExpectationCost(decisions.stakeholderExpectation);
                var respCost = (ds.events && ds.events.r2_authority) ? this._r3ResponseCost(decisions.authorityResponse) : 0;
                var r3total = ideaCost + protoBase + decisions.prototypeBudget + expCost + respCost;
                if (r3total > ds.budget - this.BUDGET_RESERVE[3]) return warn('budget_reserve_warning');

            } else if (round === 4) {
                decisions.testMethod       = this._readInt('testMethodSelect', 1, 3, 1);
                decisions.testParticipants = this._readInt('testParticipantsInput', 5, 50, 15);
                decisions.finalDecision    = this._readInt('finalDecisionSelect', 1, 3, 1);

                if (decisions.testParticipants < 5 || decisions.testParticipants > 50) return warn('participants_warning');
                var testCosts = [12000, 8000, 3000];
                var testHours = [15, 10, 5];
                var tCost = testCosts[decisions.testMethod - 1] || 8000;
                var tHours = testHours[decisions.testMethod - 1] || 10;
                if (tHours > ds.teamHours) return warn('hours_exceeded_warning');
                if ((tCost + decisions.testParticipants * 200) > ds.budget) return warn('budget_exceeded_warning');
            }
            return true;
        }

        // ---------- model ----------

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            // Idempotency (EQIL M1): recomputing a round first restores the pre-round
            // snapshot, so double-submit / undo+resubmit never compounds mutations.
            // Random rolls live in ds.events and survive the restore (no re-rolling).
            if (!ds.checkpoints) ds.checkpoints = {};
            if (ds.checkpoints[round]) {
                this._restore(ds, ds.checkpoints[round], round);
            } else {
                ds.checkpoints[round] = this._snapshot(ds);
            }

            var budgetSpent = 0;
            var hoursUsed = 0;
            var eventTriggered = null;
            var penaltiesApplied = [];

            if (round === 1) {
                var totalHours = d.interviewHours + d.observationHours + d.deskReviewHours;
                budgetSpent = (d.interviewHours * 2000) + (d.observationHours * 1500) + (d.deskReviewHours * 800);
                hoursUsed = totalHours;

                var interviewInsight = d.interviewHours * 1.5;
                var observationInsight = d.observationHours * 2.2;
                var deskInsight = d.deskReviewHours * 0.6;
                var rawInsight = interviewInsight + observationInsight + deskInsight;

                var segmentMultiplier = d.segmentFocus === 1 ? 1.4 : d.segmentFocus === 2 ? 1.0 : 0.75;
                ds.insightScore = Math.min(Math.round(rawInsight * segmentMultiplier * 0.7), 92);
                ds.empathyComplete = totalHours >= 20 && ds.insightScore >= 25;

                if (totalHours < 20) {
                    ds.processDiscipline = Math.max(ds.processDiscipline - 10, 0);
                } else {
                    ds.processDiscipline = Math.min(ds.processDiscipline + 25, 100);
                }

                if (this._roll(ds, 'r1_contradictory', 0.5)) {
                    eventTriggered = 'contradictory_finding';
                    ds.insightScore = Math.min(ds.insightScore + 8, 100);
                    // Never let event hours eat the reserve for future rounds (EQIL B1)
                    hoursUsed += Math.min(5, Math.max(0, ds.teamHours - totalHours - this.HOURS_RESERVE[1]));
                }
                ds.activeEvent = eventTriggered;

                ds.budget -= budgetSpent;
                ds.teamHours -= hoursUsed;
                this._pushHistory(ds, round, ds.insightScore);

                return {
                    period: round,
                    stage: 'empathize',
                    budgetSpent: budgetSpent,
                    hoursUsed: hoursUsed,
                    insightScore: ds.insightScore,
                    stakeholderAlignment: ds.stakeholderAlignment,
                    budgetRemaining: ds.budget,
                    hoursRemaining: ds.teamHours,
                    event: eventTriggered,
                    penalty: null
                };

            } else if (round === 2) {
                hoursUsed = d.convergenceHours;
                var stakeCost = d.stakeholderUpdate === 1 ? 5000 : d.stakeholderUpdate === 2 ? 1000 : 0;
                budgetSpent = (d.convergenceHours * 1000) + stakeCost;

                var hmwOption = this.HMW_OPTIONS.find(function(o) { return o.id === d.hmwChoice; });
                var hmwMatch = hmwOption ? hmwOption.insightMatch : 0.2;

                var clarityBase = ds.insightScore * hmwMatch;
                var convergenceFactor = Math.min(d.convergenceHours / 15, 1.5);
                ds.problemClarity = Math.min(Math.round(clarityBase * convergenceFactor), 100);
                ds.hmwChoice = d.hmwChoice;
                ds.defineComplete = true;

                if (d.stakeholderUpdate === 1) {
                    ds.stakeholderAlignment = Math.min(ds.stakeholderAlignment + 20, 100);
                } else if (d.stakeholderUpdate === 2) {
                    ds.stakeholderAlignment = Math.min(ds.stakeholderAlignment + 8, 100);
                } else {
                    ds.stakeholderAlignment = Math.max(ds.stakeholderAlignment - 15, 0);
                }

                ds.processDiscipline = Math.min(ds.processDiscipline + 25, 100);

                // Authority pressure (concept §9) is now a decision, not a narration:
                // the CEO demands a digital pivot; the TEAM chooses its response in R3.
                // No hidden cost here (EQIL B1) — consequences follow from the response.
                if (this._roll(ds, 'r2_authority', 0.4)) {
                    eventTriggered = 'authority_pressure';
                    ds.stakeholderAlignment = Math.max(ds.stakeholderAlignment - 8, 0);
                }
                ds.activeEvent = eventTriggered;

                ds.budget -= budgetSpent;
                ds.teamHours -= hoursUsed;
                this._pushHistory(ds, round, ds.problemClarity);

                return {
                    period: round,
                    stage: 'define',
                    budgetSpent: budgetSpent,
                    hoursUsed: hoursUsed,
                    problemClarity: ds.problemClarity,
                    stakeholderAlignment: ds.stakeholderAlignment,
                    budgetRemaining: ds.budget,
                    hoursRemaining: ds.teamHours,
                    event: eventTriggered,
                    penalty: null
                };

            } else if (round === 3) {
                var ideaHours = d.ideationApproach === 1 ? 20 : d.ideationApproach === 2 ? 10 : 15;
                hoursUsed = ideaHours;
                var ideaCost = d.ideationApproach === 3 ? 15000 : 0;
                var protoCosts = [5000, 8000, 25000, 35000];
                var protoBase = protoCosts[d.prototypeType - 1] || 5000;
                var expCost = this._r3ExpectationCost(d.stakeholderExpectation);
                var authorityPending = !!(ds.events && ds.events.r2_authority);
                var respCost = authorityPending ? this._r3ResponseCost(d.authorityResponse) : 0;
                budgetSpent = ideaCost + protoBase + d.prototypeBudget + expCost + respCost;

                if (!ds.empathyComplete) {
                    penaltiesApplied.push('speed_trap');
                    ds.penalties.push('speed_trap');
                }
                // Analysis paralysis (concept §8, EQIL M6): over-analysis starved the
                // build. Triggered when Rounds 1–2 consumed more than 85 of 120 hours.
                if ((120 - ds.teamHours) > 85) {
                    penaltiesApplied.push('analysis_paralysis');
                    ds.penalties.push('analysis_paralysis');
                }

                // Stakeholder expectation management (concept §7 R3, EQIL M4)
                if (d.stakeholderExpectation === 1) {
                    ds.stakeholderAlignment = Math.min(ds.stakeholderAlignment + 12, 100);
                } else if (d.stakeholderExpectation === 2) {
                    ds.stakeholderAlignment = Math.min(ds.stakeholderAlignment + 4, 100);
                } else {
                    ds.stakeholderAlignment = Math.max(ds.stakeholderAlignment - 8, 0);
                }

                // Response to the CEO's digital-pivot demand (concept §9: "tests the
                // team's ability to push back constructively")
                if (authorityPending) {
                    if (d.authorityResponse === 1) {          // push back with evidence
                        ds.stakeholderAlignment = Math.min(ds.stakeholderAlignment + 12, 100);
                        ds.processDiscipline = Math.min(ds.processDiscipline + 5, 100);
                    } else if (d.authorityResponse === 2) {   // compromise: parallel pilot
                        ds.stakeholderAlignment = Math.min(ds.stakeholderAlignment + 6, 100);
                        ds.problemClarity = Math.round(ds.problemClarity * 0.9);
                    } else {                                   // comply: build the app
                        ds.stakeholderAlignment = Math.min(ds.stakeholderAlignment + 15, 100);
                        ds.problemClarity = Math.round(ds.problemClarity * 0.75);
                        ds.processDiscipline = Math.max(ds.processDiscipline - 10, 0);
                    }
                }

                var ideationQuality = d.ideationApproach === 1 ? 0.7 : d.ideationApproach === 2 ? 0.9 : 1.0;
                var protoFidelity = d.prototypeType === 1 ? 0.4 : d.prototypeType === 2 ? 0.65 : d.prototypeType === 3 ? 0.85 : 0.9;

                var isDigitalProto = d.prototypeType === 4;
                var isRootCauseNonDigital = ds.hmwChoice === 2 || ds.hmwChoice === 4;
                var mismatchPenalty = (isDigitalProto && isRootCauseNonDigital) ? 0.6 : 1.0;

                // MVP principle (concept §3.5): fidelity should MATCH how validated the
                // problem is. Low clarity → low-fi is ideal; polish before validation is
                // resource misallocation, not a bonus.
                var idealFidelity = 0.4 + 0.005 * ds.problemClarity;
                var fidelityMatch = 1 - Math.min(Math.abs(protoFidelity - idealFidelity) * 1.2, 0.5);
                var budgetBonus = Math.min(d.prototypeBudget / 50000, 0.3) * (ds.problemClarity >= 50 ? 1 : 0.3);

                var fitBase = ds.problemClarity * ideationQuality * fidelityMatch * mismatchPenalty;
                ds.prototypeFit = Math.min(Math.round(fitBase * (1 + budgetBonus)), 100);
                ds.prototypeBuilt = true;
                ds.prototypeTypeChosen = d.prototypeType;

                ds.processDiscipline = Math.min(ds.processDiscipline + 25, 100);

                ds.budget -= budgetSpent;
                ds.teamHours -= hoursUsed;

                // Budget cut AFTER spend, clamped so Round 4 stays affordable (EQIL B1/M5).
                // Reported separately from team spending (eventCost), not mixed into it.
                var eventCost = 0;
                if (this._roll(ds, 'r3_budget_cut', 0.35)) {
                    eventTriggered = 'budget_cut';
                    eventCost = Math.min(Math.round(ds.budget * 0.25), Math.max(0, ds.budget - this.BUDGET_RESERVE[3]));
                    ds.budget -= eventCost;
                }
                ds.activeEvent = eventTriggered;
                this._pushHistory(ds, round, ds.prototypeFit);

                return {
                    period: round,
                    stage: 'ideate',
                    budgetSpent: budgetSpent,
                    eventCost: eventCost,
                    hoursUsed: hoursUsed,
                    prototypeFit: ds.prototypeFit,
                    stakeholderAlignment: ds.stakeholderAlignment,
                    budgetRemaining: ds.budget,
                    hoursRemaining: ds.teamHours,
                    event: eventTriggered,
                    penalty: penaltiesApplied[0] || null,
                    penalties: penaltiesApplied
                };

            } else if (round === 4) {
                var testCosts = [12000, 8000, 3000];
                var testHours = [15, 10, 5];
                var tCost = testCosts[d.testMethod - 1] || 8000;
                var tHours = testHours[d.testMethod - 1] || 10;
                var partCost = d.testParticipants * 200;
                budgetSpent = tCost + partCost;
                hoursUsed = tHours;

                // Discipline for completing the full cycle is earned BEFORE scoring (EQIL B2)
                ds.processDiscipline = Math.min(ds.processDiscipline + 25, 100);

                // Learning Yield (concept §7 R4): how much validated learning the test
                // generated. A quality component of the score, not a global multiplier.
                var testQuality = d.testMethod === 1 ? 1.0 : d.testMethod === 2 ? 0.85 : 0.5;
                var participantFactor = 0.4 + 0.6 * Math.min(d.testParticipants / 30, 1.0);
                ds.learningYield = Math.round(100 * testQuality * participantFactor);

                var idealDecision = 1;
                if (ds.prototypeFit < 40) {
                    idealDecision = 3;
                } else if (ds.prototypeFit < 65) {
                    idealDecision = 2;
                }
                var decisionQuality = d.finalDecision === idealDecision ? 1.0 :
                    (d.finalDecision === 2 || idealDecision === 2) ? 0.75 : 0.5;

                var speedTrapPenalty = ds.penalties.indexOf('speed_trap') >= 0 ? -15 : 0;
                var paralysisPenalty = ds.penalties.indexOf('analysis_paralysis') >= 0 ? -10 : 0;
                var wrongProblemPenalty = (ds.hmwChoice === 1 || ds.hmwChoice === 3) ? -20 : 0;

                // Additive weighted model per concept §8 (30/35/20/15), with the R4
                // test+decision as a bounded modifier (±30%), not a score-erasing one.
                var rawInnovation = (ds.insightScore * 0.30) + (ds.prototypeFit * 0.35) + (ds.stakeholderAlignment * 0.20) + (ds.processDiscipline * 0.15);
                var testModifier = 0.7 + 0.3 * (ds.learningYield / 100) * decisionQuality;
                rawInnovation = rawInnovation * testModifier;
                rawInnovation += speedTrapPenalty + paralysisPenalty + wrongProblemPenalty;
                ds.innovationScore = Math.max(Math.min(Math.round(rawInnovation), 100), 0);

                ds.activeEvent = null;
                ds.budget -= budgetSpent;
                ds.teamHours -= hoursUsed;
                this._pushHistory(ds, round, ds.innovationScore);

                return {
                    period: round,
                    stage: 'test',
                    budgetSpent: budgetSpent,
                    hoursUsed: hoursUsed,
                    innovationScore: ds.innovationScore,
                    learningYield: ds.learningYield,
                    prototypeFit: ds.prototypeFit,
                    stakeholderAlignment: ds.stakeholderAlignment,
                    budgetRemaining: ds.budget,
                    hoursRemaining: ds.teamHours,
                    event: null,
                    penalty: null
                };
            }

            return { period: round };
        }

        // ---------- UI ----------

        setupUI(uiManager) {
            var self = this;
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.budget',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('hoursDisplay', 'domainState.teamHours',
                (v) => v + this._t('hours_suffix'));
            // Hidden insight meter (concept §6, EQIL B3): teams observe insight only
            // through the feedback their prototype receives — numeric value is
            // revealed once the prototype has been built and tested.
            uiManager.bind('insightDisplay', 'domainState.insightScore', function(v) {
                var st = window.mySimulation && window.mySimulation.state;
                if (st && st.domainState && st.domainState.prototypeBuilt) return Math.round(v) + '/100';
                return self._t('insight_hidden_value');
            });
            uiManager.bind('stakeholderDisplay', 'domainState.stakeholderAlignment',
                (v) => Math.round(v) + '%');
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._t('chart_insight_series'),
                                data: [],
                                borderColor: '#8e44ad',
                                backgroundColor: 'rgba(142,68,173,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3
                            },
                            {
                                label: this._t('chart_alignment_series'),
                                data: [],
                                borderColor: '#f39c12',
                                backgroundColor: 'rgba(243,156,18,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: this._t('chart_metrics_title') } },
                        scales: { y: { beginAtZero: true, max: 100 } }
                    }
                },
                budgetChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: this._t('chart_budget_series'),
                            data: [],
                            backgroundColor: 'rgba(39,174,96,0.6)',
                            borderColor: '#27ae60',
                            borderWidth: 2
