        getChartData(state) {
            var self = this;
            var stageKeys = ['stage_empathize', 'stage_define', 'stage_ideate', 'stage_test'];
            var labels = state.domainState.insightHistory.map(function(_, i) {
                return stageKeys[i] ? self._t(stageKeys[i]) : ('R' + (i + 1));
            });
            return {
                scoreChart: {
                    labels: labels,
