                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = window.mySimulation.state.domainState;
            var finalScore = ds.innovationScore || 0;

            var bucket = 'beginner';
            if (finalScore >= 70) bucket = 'excellent';
            else if (finalScore >= 50) bucket = 'good';
            else if (finalScore >= 30) bucket = 'developing';
            // canonical English value kept for any programmatic consumer;
            // performanceLabel is the user-facing translated string
            var performance = { beginner: 'Beginner', developing: 'Developing', good: 'Good', excellent: 'Excellent' }[bucket];

            // Debrief payload (concept §11, EQIL I5): explain WHERE the score came
            // from so the facilitator can run the said/needed + speed-vs-depth debrief.
            var insights = [];
            if (ds.penalties.indexOf('speed_trap') >= 0) insights.push(this._t('summary_speed_trap'));
            if (ds.penalties.indexOf('analysis_paralysis') >= 0) insights.push(this._t('summary_paralysis'));
            if (ds.hmwChoice === 2) insights.push(this._t('summary_hmw_correct'));
            else if (ds.hmwChoice === 4) insights.push(this._t('summary_hmw_good'));
            else insights.push(this._t('summary_hmw_wrong'));
            if ((ds.stakeholderAlignment || 0) >= 70) insights.push(this._t('summary_alignment_strong'));
            if ((ds.prototypeFit || 0) >= 60) insights.push(this._t('summary_fit_strong'));
            if ((ds.learningYield || 0) < 60) insights.push(this._t('summary_low_learning'));
            if (ds.events && ds.events.r2_authority) insights.push(this._t('summary_authority_faced'));

            return {
                innovationScore: finalScore,
                insightDepth: ds.insightScore || 0,
                prototypeFit: ds.prototypeFit || 0,
                stakeholderAlignment: ds.stakeholderAlignment || 0,
                processDiscipline: ds.processDiscipline || 0,
                learningYield: ds.learningYield || 0,
                performance: performance,
                performanceLabel: this._t('perf_' + bucket),
                insights: insights
            };
        }

        getHint(state, results) {
            var round = state.currentPeriod;
            if (round === 1 && state.domainState.insightScore < 25) {
                return window.mySimulation.t('hint_low_insight');
            }
            if (round === 2 && state.domainState.stakeholderAlignment < 30) {
                return window.mySimulation.t('hint_low_alignment');
            }
            if (round === 3 && state.domainState.prototypeFit < 30) {
                return window.mySimulation.t('hint_poor_fit');
            }
            if (results && results.penalties && results.penalties.indexOf('analysis_paralysis') >= 0) {
                return window.mySimulation.t('hint_analysis_paralysis');
            }
            if (results && results.penalty === 'speed_trap') {
                return window.mySimulation.t('hint_speed_trap');
            }
            if (results && results.event === 'budget_cut') {
                return window.mySimulation.t('hint_budget_cut');
            }
            return null;
        }

