        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefIcon = document.getElementById('briefingIcon');
            if (briefIcon) briefIcon.innerHTML = round.icon;

            var briefText = document.getElementById('briefingText');
            if (briefText) briefText.innerHTML = this._t(round.briefKey);

            var stageEl = document.getElementById('stageDisplay');
            if (stageEl) stageEl.innerHTML = this._t(round.stageKey);

            var panels = ['round1Panel', 'round2Panel', 'round3Panel', 'round4Panel'];
            for (var i = 0; i < panels.length; i++) {
                var panel = document.getElementById(panels[i]);
                if (panel) panel.style.display = (i === idx) ? 'block' : 'none';
            }

            // The CEO-response decision only appears if authority pressure actually fired (EQIL I4)
            var respGroup = document.getElementById('authorityResponseGroup');
            if (respGroup) {
                var pending = !!(state.domainState && state.domainState.events && state.domainState.events.r2_authority);
                respGroup.style.display = (idx === 2 && pending) ? 'block' : 'none';
            }

            var eventPanel = document.getElementById('eventPanel');
            if (eventPanel && state.domainState && state.domainState.activeEvent) {
                var evt = state.domainState.activeEvent;
                var titleEl = document.getElementById('eventTitle');
                var descEl = document.getElementById('eventDesc');
                if (evt === 'contradictory_finding' && titleEl && descEl) {
                    titleEl.innerHTML = this._t('event_contradictory');
                    descEl.innerHTML = this._t('event_contradictory_desc');
                    eventPanel.style.display = 'block';
                } else if (evt === 'authority_pressure' && titleEl && descEl) {
                    titleEl.innerHTML = this._t('event_authority');
                    descEl.innerHTML = this._t('event_authority_desc');
                    eventPanel.style.display = 'block';
                } else if (evt === 'budget_cut' && titleEl && descEl) {
                    titleEl.innerHTML = this._t('event_budget_cut');
                    descEl.innerHTML = this._t('event_budget_cut_desc');
                    eventPanel.style.display = 'block';
                } else {
                    eventPanel.style.display = 'none';
                }
            } else if (eventPanel) {
                eventPanel.style.display = 'none';
            }

            // Localized text alternatives for the canvas charts (WCAG 1.1.1, EQIL I6)
            var scoreCanvas = document.getElementById('scoreChart');
            if (scoreCanvas) scoreCanvas.setAttribute('aria-label', this._t('aria_score_chart'));
            var budgetCanvas = document.getElementById('budgetChart');
            if (budgetCanvas) budgetCanvas.setAttribute('aria-label', this._t('aria_budget_chart'));

            this._updateScoreBars(state);
        }

        _updateScoreBars(state) {
            var ds = state.domainState;
            if (!ds) return;
            var hidden = !ds.prototypeBuilt; // concept §6: insight is hidden until prototype feedback

            var setBar = function(barId, valId, value, show) {
                var bar = document.getElementById(barId);
                var val = document.getElementById(valId);
                var v = Math.round(value || 0);
                if (bar) {
                    bar.style.width = (show ? v : 0) + '%';
                    bar.setAttribute('aria-valuenow', show ? v : 0);
                }
                if (val) val.textContent = show ? v : '—';
            };
            setBar('insightBar', 'insightScoreVal', ds.insightScore, !hidden);
            setBar('fitBar', 'fitScoreVal', ds.prototypeFit, true);
            setBar('alignmentBar', 'alignmentScoreVal', ds.stakeholderAlignment, true);
            setBar('disciplineBar', 'disciplineScoreVal', ds.processDiscipline, true);
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new DesignThinkAdapter(), {
            simulationType: 'designthink_innovation',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
